def f(g):
    n,m=len(g),len(g[0])
    vals=[x for row in g for x in row]
    cntv={}
    for v in vals: cntv[v]=cntv.get(v,0)+1
    bg=max(cntv,key=cntv.get)
    hsz=[r for r in range(n) if len({g[r][c] for c in range(m)})==1]
    vsz=[c for c in range(m) if len({g[r][c] for r in range(n)})==1]
