    cnts=[]
    for i,(a,b) in enumerate(zip(hs,hs[1:])):
        for j,(x,y) in enumerate(zip(vs,vs[1:])):
            cnt=sum(1 for r in range(a+1,b) for c in range(x+1,y) if g[r][c]!=bg and g[r][c]!=g[a][x])
            cnts.append((cnt,i,j,a,b,x,y))
    mx=max(cnt for cnt,i,j,a,b,x,y in cnts)
    for cnt,i,j,a,b,x,y in cnts:
        if cnt==mx:
            nonbg={g[r][c] for r in range(a+1,b) for c in range(x+1,y) if g[r][c]!=bg}
            tgt=nonbg-{g[a][x]}  # exclude separator color
            # if tie between two candidate colors pick by count inside region
            if len(tgt)>1:
                tt={k:sum(1 for r in range(a+1,b) for c in range(x+1,y) if g[r][c]==k) for k in tgt}
                tgt=max(tt,key=tt.get)
            for r in range(a+1,b):
                for c in range(x+1,y): res[r][c]=tgt
    return res
