        for r in range(reg[0]+1,reg[1]):
            for c in range(reg[2]+1,reg[3]): res[r][c]=tgt
    if not fillties and len(filled)>1:
        # no fill; just clear all markers
        for reg,c in reginfo:
            for r in range(reg[0]+1,reg[1]):
                for c2 in range(reg[2]+1,reg[3]): res[r][c2]=bg
    else:
